"""Bind an original crossing-capped region without reading any coordinates.

The region planner proves original complete route inventories. These checks
bind that declaration to current private tables, preserving exact Section ends
and requiring the crossing corridor at both declared tail owners. This module
supplies the opt-in shared dispatch without claiming complete Bundle coverage.
"""
from .curved_separator_chain_bindings import _rows, _unique


def resolve(item, columns, owners):
    mapping = _rows(columns['Mapping'],('st_ps_street_id','st_ps_first_section','st_ps_last_section'))
    spans = _unique(mapping,'original span')
    corridors = _rows(columns['Corridors'],('st_cs_span_index','st_cs_street_id','st_cs_start_index','st_cs_end_index'))
    span_rows = _unique((r[0] for r in corridors),'corridor span')
    approaches = _rows(columns['Approaches'],('st_cj_street_id','st_cj_section_id','st_cj_reverse','st_cj_junction_id'))
    ports = _unique((r[:3] for r in approaches),'original endpoint')
    if len(set(owners.values()))!=len(owners): raise ValueError('Repeated native patch owner')
    groups={}
    for sites,owner in owners.items():
        if type(owner) is not int or not 0<=owner<2**20:
            raise ValueError('Patch index must be a bounded integer')
        for site in sites:
            if site in groups: raise ValueError('Original site has multiple patch owners')
            groups[site]=sites
    def owner(sites):
        if sites not in owners: raise ValueError('Region lost an original surface owner')
        return owners[sites]
    def corridor(identity):
        if identity not in spans or spans[identity] not in span_rows:
            raise ValueError('Region lost an original corridor span')
        row=span_rows[spans[identity]]; span,sid,start,end=corridors[row]
        if (sid!=identity[0] or not 0<=start<len(approaches) or not 0<=end<len(approaches) or
                approaches[start][:3]!=(sid,identity[1],0) or approaches[end][:3]!=(sid,identity[2],1)):
            raise ValueError('Corridor no longer matches its original Street and Section ends')
        return row
    def endpoint(end,sites):
        key=(end.street_id,end.section_id,end.end)
        if key not in ports: raise ValueError('Region lost its original endpoint')
        port=ports[key]
        if approaches[port][3] not in sites: raise ValueError('Endpoint left its original surface owner')
        return port
    if any(len(v)!=2 for v in (item.member_street_ids,item.member_span_ids,item.intermediate_sites,
                                item.head_ends,item.tail_ends,item.tail_sites,item.crossing_ends)):
        raise ValueError('Crossing region needs two exact member sides')
    record=dict(bundle_id=item.bundle_id,member_a=item.member_street_ids[0],member_b=item.member_street_ids[1],
                head_patch=owner(item.head_sites),tail_a_patch=owner(item.tail_sites[0]),
                tail_b_patch=owner(item.tail_sites[1]),crossing_corridor=corridor(item.crossing_span_id),
                crossing_street=item.crossing_span_id[0],tail_patch=-1,kind=4)
    if len({record[k] for k in ('head_patch','tail_a_patch','tail_b_patch')})!=3:
        raise ValueError('Attached cap and both crossing owners must be distinct')
    rules=[];selected_members=[];cross_ports=[]
    for side,(sid,identities,middle) in enumerate(zip(item.member_street_ids,item.member_span_ids,item.intermediate_sites)):
        if not identities or len(middle)!=len(identities)-1 or any(i[0]!=sid for i in identities):
            raise ValueError('Region needs an ordered member chain with every intermediate owner')
        rows=[corridor(i) for i in identities]
        if len(rows)!=len(set(rows)): raise ValueError('Repeated region member corridor')
        selected_members.extend(rows)
        first=endpoint(item.head_ends[side],item.head_sites)
        last=endpoint(item.tail_ends[side],item.tail_sites[side])
        if item.head_ends[side].street_id!=sid or item.tail_ends[side].street_id!=sid:
            raise ValueError('Member endpoints changed original Street')
        enter=first
        for index,row in enumerate(rows):
            pair=corridors[row][2:]
            if enter not in pair: raise ValueError('Region member is disconnected or out of order')
            leave=pair[1] if pair[0]==enter else pair[0]
            if index==len(rows)-1:
                if leave!=last: raise ValueError('Region member misses its declared crossing end')
            else:
                site=approaches[leave][3]
                if groups.get(site)!=middle[index]: raise ValueError('Region intermediate owner changed')
                following=[p for p in corridors[rows[index+1]][2:] if approaches[p][3]==site]
                if len(following)!=1: raise ValueError('Adjacent region corridors lost their original junction')
                enter=following[0]
        prefix='a_' if side==0 else 'b_'
        record[prefix+'head']=first;record[prefix+'tail']=last
        rules.extend((side,1,row) for row in rows)
        rules.extend((side,0,owner(sites)) for sites in middle)
        crossing_end=item.crossing_ends[side]
        port=endpoint(crossing_end,item.tail_sites[side])
        if (crossing_end.street_id!=item.crossing_span_id[0] or
                port not in corridors[record['crossing_corridor']][2:] or
                approaches[port][3]!=approaches[last][3]):
            raise ValueError('Crossing must meet the member at the exact original junction')
        cross_ports.append(port)
    if len(set(selected_members))!=len(selected_members) or record['crossing_corridor'] in selected_members:
        raise ValueError('Crossing and member spans must be distinct')
    if len(set(cross_ports))!=2: raise ValueError('Crossing must join both original members')
    if len({record[k] for k in ('a_head','a_tail','b_head','b_tail')})!=4:
        raise ValueError('Region needs four distinct original mouth ports')
    rules.extend(((2,0,record['head_patch']),(3,0,record['tail_a_patch']),
                  (3,0,record['tail_b_patch']),(3,1,record['crossing_corridor'])))
    if len(rules)>512 or len(rules)!=len(set(rules)):
        raise ValueError('Region owner permissions must be unique and bounded')
    return record,tuple(rules)


def bind_mixed(preparation, region_preparation, tables, label, *, free_chains=False, longitudinal_chains=False):
    """Append opt-in regions without changing any existing separator record."""
